	public Infobar updateInfobar(List<Scene> scenes, MatchAllData match, List<MatchAllData> tournament_matches,
			boolean show_speed, List<PrintWriter> print_writer) throws InterruptedException, IOException {
		if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0 || match.getMatch().getInning().get(1).getTotalWickets() >= 10
				|| CricketFunctions.GetTargetData(match).getRemaningBall() == 0) {
			if (infobar.isResult_on_screen() == false) {

				infobar.setIdent_section("RESULT");

				print_writer.get(0).println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Ident$IdentTeamGrp1$txt_TeamName*GEOM*TEXT SET "
								+ match.getSetup().getHomeTeam().getTeamName1() + "\0");
				print_writer.get(0).println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Ident$IdentTeamGrp2$txt_TeamName*GEOM*TEXT SET "
								+ match.getSetup().getAwayTeam().getTeamName1() + "\0");

				print_writer.get(0).println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Ident$IdentBadges$HomeBadge$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
								+ logo_path + match.getSetup().getHomeTeam().getTeamBadge() + " \0");
				print_writer.get(0).println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Ident$IdentBadges$AwayBadge$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
								+ logo_path + match.getSetup().getAwayTeam().getTeamBadge() + " \0");

				print_writer.get(0).println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Ident$IdentInfoGrp$txt_IdentInfo*GEOM*TEXT SET "
								+ CricketFunctions.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL, "|",broadcaster,true).getTargetOrResult()
										.toUpperCase()
								+ "\0");

				TimeUnit.MILLISECONDS.sleep(400);
				AnimateOutGraphics(print_writer.get(0), "ANIMATE-OUT-INFOBAR");
				TimeUnit.MILLISECONDS.sleep(400);
				processAnimation(print_writer.get(0), "MainIn", "SHOW 0.0", broadcaster);
				TimeUnit.MILLISECONDS.sleep(400);
				AnimateInGraphics(print_writer.get(0), "IDENT");
				TimeUnit.MILLISECONDS.sleep(200);
				which_graphic_on_screen = "IDENT";
				infobar.setInfobar_on_screen(true);
				infobar.setResult_on_screen(true);
			}
		} else if (infobar.isInfobar_on_screen() == true) {
			if (infobar.getIdent_section() != null && !infobar.getIdent_section().trim().isEmpty()) {
				infobar = populateInfobarIdent(infobar, true, scenes.get(0).getScene_path(), print_writer.get(0), match,
						broadcaster);
			} else {
				infobar = populateInfobarTeamScore(infobar, true, print_writer.get(0), match, broadcaster);
				infobar = populateVizInfobarMiddle(infobar, true, print_writer.get(0), match, broadcaster);

				if (infobar.getBottom_right_section() != null && !infobar.getBottom_right_section().trim().isEmpty()) {
					infobar = populateVizInfobarRight(infobar, true, print_writer.get(0), match, broadcaster);
					if (CricketFunctions.getCurrentInningCurrentBowler(match) != null) {
						infobar.setLast_bowler(CricketFunctions.getCurrentInningCurrentBowler(match));
					}
				} else {
					infobar = populateVizInfobarRightTop(infobar, true, print_writer.get(0), match, broadcaster);
					infobar = populateVizInfobarRightBottom(infobar, true, print_writer.get(0), match, broadcaster);
				}

				if (infobar.getFull_section() != null && !infobar.getFull_section().trim().isEmpty()) {
					infobar = populateSection5(infobar, true, print_writer.get(0), 0, match, broadcaster);
				}
				if (infobar.getLast_top_section() != null && !infobar.getLast_top_section().trim().isEmpty()) {
					infobar = populateVizInfobarTop(infobar, true, print_writer.get(0), match, broadcaster);
				}
			}

			System.out.println("info = " + infobar.getLast_speed_value());
			System.out.println("match = " + match.getMatch().getCurrent_speed());
			// infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
			if (infobar.getLast_speed_value() == null) {
				if (match.getMatch().getCurrent_speed() != null) {
					speed(print_writer.get(0), match);
				}
				// infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
			} else if (infobar.getLast_speed_value() != null || !infobar.getLast_speed_value().isEmpty()) {
				System.out.println("info speed = " + infobar.getLast_speed_value());
				System.out.println("match speed = " + match.getMatch().getCurrent_speed());
				if (!infobar.getLast_speed_value().equalsIgnoreCase(match.getMatch().getCurrent_speed())) {
					System.out.println("info speed1 = " + infobar.getLast_speed_value());
					System.out.println("match speed1 = " + match.getMatch().getCurrent_speed());
					speed(print_writer.get(0), match);
				} else {
					for (Inning inn : match.getMatch().getInning()) {
						if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
							if (!infobar.getLast_ball_value().equalsIgnoreCase(String.valueOf(inn.getTotalBalls()))
									|| !infobar.getLast_wide_value()
											.equalsIgnoreCase(String.valueOf(inn.getTotalWides()))
									|| !infobar.getLast_noball_value()
											.equalsIgnoreCase(String.valueOf(inn.getTotalNoBalls()))) {
								System.out.println("info speed2 = " + infobar.getLast_speed_value());
								System.out.println("match speed2 = " + match.getMatch().getCurrent_speed());
								speed(print_writer.get(0), match);
							}
						}
					}
				}
			}

			if (infobar.isShow_winner() == false) {
				showWinner(infobar, print_writer.get(0), match);
			}

		}
		return infobar;
	}

	public void speed(PrintWriter print_writer, MatchAllData match) throws IOException, InterruptedException {
		if (match.getMatch().getCurrent_speed() != null && !match.getMatch().getCurrent_speed().isEmpty()) {
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data1*GEOM*TEXT SET "
							+ "BALL SPEED - " + "\0");
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Section3$Section3All$BallSpeed$img_Text$txt_Data2*GEOM*TEXT SET "
							+ match.getMatch().getCurrent_speed() + " KPH" + "\0");

			processAnimation(print_writer, "Section3$BallSpeedIn", "START", broadcaster);
			infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
		}
	}

	public void showWinner(Infobar infobar, PrintWriter print_writer, MatchAllData match) throws InterruptedException {
		if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0 || match.getMatch().getInning().get(1).getTotalWickets() >= 10
				|| CricketFunctions.GetTargetData(match).getRemaningBall() == 0) {

			if (infobar.getLast_middle_section() != null && !infobar.getLast_middle_section().trim().isEmpty()) {

				switch (infobar.getLast_middle_section().toUpperCase()) {
				case "EQUATION":
					processAnimation(print_writer, "Section3$EquationOut", "START", broadcaster);
					break;
				case "PROJECTED":
					processAnimation(print_writer, "Section3$ProjectedOut", "START", broadcaster);
					break;
				case "LAST_BOUNDARY":
					processAnimation(print_writer, "Section3$BallsSinceLastBoundaryOut", "START", broadcaster);
					break;
				case "BOUNDARIES":
					processAnimation(print_writer, "Section3$BoundariesOut", "START", broadcaster);
					break;
				case "LAST_WICKET":
					processAnimation(print_writer, "Section3$LastWicketOut", "START", broadcaster);
					break;
				case "TOURNAMENT-NAME":
					processAnimation(print_writer, "Section3$FreeTextSmallOut", "START", broadcaster);
					break;
				case "BATSMAN":
					processAnimation(print_writer, "Section3$Section3In", "START", broadcaster);
					break;
				}

				TimeUnit.MILLISECONDS.sleep(200);
				print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tFreeTextSmallText" + " SET " + CricketFunctions
								.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL, "|",broadcaster,true).getTargetOrResult().toUpperCase()
						+ "\0");
				processAnimation(print_writer, "Section3$FreeTextSmallIn", "START", broadcaster);
				infobar.setLast_middle_section(null);
				infobar.setMiddle_section(null);

			}
		}
	}

