	public static Statistics updateTournamentDataWithStats(Statistics stat, List<MatchAllData> tournament_matches,
			MatchAllData currentMatch) {
		boolean player_found = false;
		for (MatchAllData match : tournament_matches) {
			if (!match.getMatch().getMatchFileName().equalsIgnoreCase(currentMatch.getMatch().getMatchFileName())) {
				if (stat.getStats_type().getStatsShortName().equalsIgnoreCase("PR")) {
					for (Inning inn : match.getMatch().getInning()) {
						for (BattingCard bc : inn.getBattingCard()) {
							if (bc.getPlayerId() == stat.getPlayerID()) {
								player_found = true;
								if (bc.getBatsmanInningStarted() != null
										&& bc.getBatsmanInningStarted().equalsIgnoreCase(CricketUtil.YES)) {
									stat.setInnings(stat.getInnings() + 1);
								}
								stat.setRuns(stat.getRuns() + bc.getRuns());
								stat.setFours(stat.getFours() + bc.getFours());
								stat.setSixes(stat.getSixes() + bc.getSixes());
								stat.setBallsFaced(stat.getBallsFaced() + bc.getBalls());

								if (bc.getRuns() < 50 && bc.getRuns() >= 30) {
									stat.setThirties(stat.getThirties() + 1);
								} else if (bc.getRuns() < 100 && bc.getRuns() >= 50) {
									stat.setFifties(stat.getFifties() + 1);
								} else if (bc.getRuns() >= 100) {
									stat.setHundreds(stat.getHundreds() + 1);
								}

							}
						}
						if (inn.getBowlingCard() != null && inn.getBowlingCard().size() > 0) {
							for (BowlingCard boc : inn.getBowlingCard()) {
								if (boc.getPlayerId() == stat.getPlayerID()) {
									stat.setWickets(stat.getWickets() + boc.getWickets());
									stat.setRunsConceded(stat.getRunsConceded() + boc.getRuns());
									stat.setBallsBowled(
											stat.getBallsBowled() + (boc.getOvers() * 6 + boc.getBalls()));
									stat.setDotBowled(stat.getDotBowled() + boc.getDots());
									if (boc.getWickets() < 5 && boc.getWickets() >= 3) {
										stat.setPlus3(stat.getPlus3() + 1);
									} else if (boc.getWickets() >= 5) {
										stat.setPlus5(stat.getPlus5() + 1);
									}
								}
							}
						}
					}
					player_found = false;
					for (Player hs : match.getSetup().getHomeSquad()) {
						if (stat.getPlayerID() == hs.getPlayerId()) {
							player_found = true;
						}
					}
					for (Player as : match.getSetup().getAwaySquad()) {
						if (stat.getPlayerID() == as.getPlayerId()) {
							player_found = true;
						}
					}
					if (player_found == true) {
						stat.setMatches(stat.getMatches() + 1);
					}
				}
			}
		}
		return stat;
	}

	public static Statistics updateStatisticsWithMatchData(Statistics stat, MatchAllData match) {
		boolean player_found = false;

		if (stat.getStats_type().getStatsShortName().equalsIgnoreCase("PR")) {
			stat.setTournament_fours(stat.getTournament_fours() + match.getMatch().getInning().get(0).getTotalFours());
			stat.setTournament_fours(stat.getTournament_fours() + match.getMatch().getInning().get(1).getTotalFours());
			for (Inning inn : match.getMatch().getInning()) {
				for (BattingCard bc : inn.getBattingCard()) {
					if (bc.getPlayerId() == stat.getPlayerID()) {
						player_found = true;
						if (bc.getBatsmanInningStarted() == null) {
						} else if (bc.getBatsmanInningStarted().equalsIgnoreCase(CricketUtil.YES)) {
							stat.setInnings(stat.getInnings() + 1);
						}

						stat.setRuns(stat.getRuns() + bc.getRuns());
						stat.setFours(stat.getFours() + bc.getFours());
						stat.setSixes(stat.getSixes() + bc.getSixes());
						stat.setBallsFaced(stat.getBallsFaced() + bc.getBalls());

						if (bc.getRuns() < 50 && bc.getRuns() >= 30) {
							stat.setThirties(stat.getThirties() + 1);
						} else if (bc.getRuns() < 100 && bc.getRuns() >= 50) {
							stat.setFifties(stat.getFifties() + 1);
						} else if (bc.getRuns() >= 100) {
							stat.setHundreds(stat.getHundreds() + 1);
						}
					}
				}
				if (inn.getBowlingCard() != null && inn.getBowlingCard().size() > 0) {
					for (BowlingCard boc : inn.getBowlingCard()) {
						if (boc.getPlayerId() == stat.getPlayerID()) {
							player_found = true;
							stat.setWickets(stat.getWickets() + boc.getWickets());
							stat.setRunsConceded(stat.getRunsConceded() + boc.getRuns());
							stat.setBallsBowled(stat.getBallsBowled() + (boc.getOvers() * 6 + boc.getBalls()));
							stat.setDotBowled(stat.getDotBowled() + boc.getDots());
							// System.out.println(boc.getWickets());
							if (boc.getWickets() >= 3 && boc.getWickets() < 5) {
								stat.setPlus3(stat.getPlus3() + 1);
							} else if (boc.getWickets() >= 5) {
								stat.setPlus5(stat.getPlus5() + 1);
							}
						}
					}
				}
			}
			player_found = false;
			for (Player hs : match.getSetup().getHomeSquad()) {
				if (stat.getPlayerID() == hs.getPlayerId()) {
					player_found = true;
				}
			}
			for (Player as : match.getSetup().getAwaySquad()) {
				if (stat.getPlayerID() == as.getPlayerId()) {
					player_found = true;
				}
			}
			if (player_found == true) {
				stat.setMatches(stat.getMatches() + 1);
			}
		}
		return stat;
	}

	public void processAnimation(PrintWriter print_writer, String animationName, String animationCommand,
			String which_broadcaster) {
		switch (which_broadcaster.toUpperCase()) {
		case "DOAD_VIZ":
		case "NEPAL_T20":
		case "MPL":
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*" + animationName + " " + animationCommand + " \0");
			break;
		case "DOAD_EVEREST":
			print_writer.println("LAYER1*EVEREST*STAGE*DIRECTOR*" + animationName + " " + animationCommand + ";");

			break;
		}

	}

	public String resetInfobarAnimation(PrintWriter print_writer, String which_frame)
			throws InterruptedException, IOException {

		switch (which_frame.toUpperCase()) {
		case "FF_FRAME":
			if (infobar.isInfobar_on_screen() == true) {
				AnimateOutGraphics(print_writer, "FFOut");
				which_graphic_on_screen = "SCOREBUG";
			}
			break;
		case "LT_FRAME":
			if (infobar.isInfobar_on_screen() == true) {
				AnimateOutGraphics(print_writer, "LTOut");
				which_graphic_on_screen = "SCOREBUG";
			}
			break;
		}
		return "";
	}

	public void Preview(PrintWriter print_writer, String viz_scene, String previous_gfx, String current_gfx)
			throws InterruptedException {
		String previewAnim = "";
		if (previous_gfx == "") {
			switch (current_gfx) {
			case "SCORECARD":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png In 4.000 BattingCard_In 2.880 \0");
				TimeUnit.MILLISECONDS.sleep(200);
				break;
			case "BOWLINGCARD":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png In 4.000 BowlingCard_In 2.880 \0");
				TimeUnit.MILLISECONDS.sleep(200);
				break;
			case "MATCHSUMMARY":
				print_writer.println(
						"-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 4.000 Summary_In 1.900 \0");
				TimeUnit.MILLISECONDS.sleep(200);
				break;
			case "TEAMLINEUP":
			case "TEAMLINEUP_SUBS":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.png In 4.000 Team$Team1_In 3.420 Team$Team1_In$TeamEssentials_In 1.700 "
						+ "Team$Team1_In$Type2_In 1.800 Team$Team1_In$Type4_In 3.420 \0");
				TimeUnit.MILLISECONDS.sleep(200);
				break;
			}
		} else {
			switch (previous_gfx) {
			case "BATBALLSUMMARY_SCORECARD":
				previewAnim = "BattingCardOut 1.020";
				break;
			case "BATBALLSUMMARY_BOWLINGCARD":
				previewAnim = "BowlingCardOut 1.020";
				break;
			case "BATBALLSUMMARY_MATCHSUMMARY":
				previewAnim = "SummaryOut 1.100";
				break;
			}
			switch (current_gfx) {
			case "SCORECARD":
				previewAnim = previewAnim + " BattingCard_In 2.880";
				break;
			case "BOWLINGCARD":
				previewAnim = previewAnim + " BowlingCard_In 2.880";
				break;
			case "MATCHSUMMARY":
				previewAnim = previewAnim + " Summary_In 1.900";
				break;
			}
			print_writer
					.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png " + previewAnim + " \0");
		}
	}

