	public void populateBugDismissal(PrintWriter print_writer, String viz_scene, int whichInning, String statsType,
			int playerId, MatchAllData match, String broadcaster) throws InterruptedException {
		if (match == null) {
			System.out.println("ERROR: populateBugDismissal -> Match is null");
		} else if (match.getMatch().getInning() == null) {
			System.out.println("ERROR: populateBugDismissal -> inning is null");
		} else {

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					switch (statsType.toUpperCase()) {
					case CricketUtil.BATSMAN:
						for (BattingCard bc : inn.getBattingCard()) {
							if (bc.getPlayerId() == playerId) {

								print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
										+ "tInfo5" + " SET " + "" + "\0");

								if (bc.getPlayer().getSurname() != null) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo1" + " SET " + bc.getPlayer().getFirstname() + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo2" + " SET " + bc.getPlayer().getSurname() + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo2" + " SET " + "" + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo1" + " SET " + bc.getPlayer().getFirstname() + "\0");
								}

								if (bc.getStatus().equalsIgnoreCase(CricketUtil.OUT)) {
									if (bc.getHowOut().equalsIgnoreCase(CricketUtil.RUN_OUT)) {
										if (CricketFunctions
												.checkImpactPlayerBowler(match.getEventFile().getEvents(), whichInning,
														bc.getHowOutFielderId())
												.equalsIgnoreCase(CricketUtil.YES)
												|| CricketFunctions
														.checkImpactPlayer(match.getEventFile().getEvents(),
																whichInning, bc.getHowOutFielderId())
														.equalsIgnoreCase(CricketUtil.YES)) {

											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tInfo3" + " SET " + bc.getHowOutPartOne() + " ("
															+ bc.getHowOutPartTwo().split(" ")[0] + ")" + "\0");

										} else {
											if (bc.getHowOutPartTwo() != null
													&& bc.getHowOutPartTwo().equalsIgnoreCase(CricketUtil.SUBSTITUTE)) {
												print_writer.println(
														"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
																+ "tInfo3" + " SET " + bc.getHowOutPartOne() + "\0");
											} else {
												print_writer.println(
														"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
																+ "tInfo3" + " SET " + bc.getHowOutText() + "\0");
											}
//											print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo3" + " SET " + bc.getHowOutText() + "\0");

										}
									} else if (bc.getHowOut().equalsIgnoreCase(CricketUtil.CAUGHT)) {
										if (CricketFunctions
												.checkImpactPlayerBowler(match.getEventFile().getEvents(), whichInning,
														bc.getHowOutFielderId())
												.equalsIgnoreCase(CricketUtil.YES)
												|| CricketFunctions
														.checkImpactPlayer(match.getEventFile().getEvents(),
																whichInning, bc.getHowOutFielderId())
														.equalsIgnoreCase(CricketUtil.YES)) {

											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tInfo3" + " SET "
															+ bc.getHowOutPartOne().replace("(SUB)", "") + " "
															+ bc.getHowOutPartTwo() + "\0");

										} else {
											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tInfo3" + " SET " + bc.getHowOutText() + "\0");
										}
									} else {
										if (bc.getHowOutPartOne() != null
												&& bc.getHowOutPartOne().equalsIgnoreCase("c substitute")) {
											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tInfo3" + " SET " + bc.getHowOutPartTwo() + "\0");
										} else {
											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tInfo3" + " SET " + bc.getHowOutText() + "\0");
										}
									}

									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo4" + " SET " + bc.getRuns() + " (" + bc.getBalls() + ")" + "\0");

								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo3" + " SET " + "S/R : " + bc.getStrikeRate() + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo4" + " SET " + bc.getRuns() + " (" + bc.getBalls() + ")" + "\0");
								}
							}
						}
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 0.714 \0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}

