	public void populateBug(PrintWriter print_writer, String viz_scene, int whichInning, String statsType, int playerId,
			MatchAllData match, String broadcaster) throws InterruptedException {
		if (match == null) {
			System.out.println("ERROR: populateBug -> Match is null");
		} else if (match.getMatch().getInning() == null) {
			System.out.println("ERROR: populateBug -> inning is null");
		} else {

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					switch (statsType.toUpperCase()) {
					case CricketUtil.BATSMAN:
						for (BattingCard bc : inn.getBattingCard()) {
							if (bc.getPlayerId() == playerId) {
								if (bc.getStatus().toUpperCase().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
									print_writer.println(
											"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo4"
													+ " SET " + bc.getRuns() + "* " + "(" + bc.getBalls() + ")" + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo4" + " SET " + bc.getRuns() + " (" + bc.getBalls() + ")" + "\0");
								}

								if (bc.getPlayer().getSurname() != null) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo1" + " SET " + bc.getPlayer().getFirstname() + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo2" + " SET " + bc.getPlayer().getSurname() + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo2" + " SET " + "" + "\0");
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tInfo1" + " SET " + bc.getPlayer().getFirstname() + "\0");
								}

								print_writer
										.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo3"
												+ " SET " + "4s : " + bc.getFours() + " 6s : " + bc.getSixes() + "\0");
								print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
										+ "tInfo5" + " SET " + "S/R : " + bc.getStrikeRate() + "\0");

							}
						}
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 0.714 \0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}

