	public void populateLTNextToBat(PrintWriter print_writer, String viz_scene, List<Statistics> stats,
			List<Player> plyr, MatchAllData match, String broadcaster, Configuration config)
			throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			this.status = CricketUtil.SUCCESSFUL;
			int row_id = 0;
			double strike_rate = 0;

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
									+ logo_path + inn.getBatting_team().getTeamBadge() + "\0");

					for (int b = 1; b <= inn.getBattingCard().size(); b++) {

						if (inn.getBattingCard().get(b - 1).getStatus().equalsIgnoreCase(CricketUtil.STILL_TO_BAT)
								&& inn.getBattingCard().get(b - 1).getHowOut() != null && inn.getBattingCard()
										.get(b - 1).getHowOut().equalsIgnoreCase(CricketUtil.RETIRED_HURT)) {

							retired_player = true;

						} else if (inn.getBattingCard().get(b - 1).getStatus()
								.equalsIgnoreCase(CricketUtil.STILL_TO_BAT)) {
							row_id = row_id + 1;
							if (row_id <= 3) {
								if (retired_player == true) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tPosition" + row_id + " SET " + (b - 1) + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "tPosition" + row_id + " SET " + b + "\0");
								}

								print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
										+ "tPlayerName" + row_id + " SET "
										+ inn.getBattingCard().get(b - 1).getPlayer().getTicker_name() + "\0");

								for (Statistics st : stats) {
									if (st.getPlayerID() == inn.getBattingCard().get(b - 1).getPlayerId()
											&& st.getStatsTypeId() == 3) {
										if (st.getBallsFaced() == 0 || st.getRuns() == 0) {
											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tStrikeRate" + row_id + " SET " + "-" + "\0");
										} else {
											strike_rate = st.getRuns() * 100;
											strike_rate = strike_rate / st.getBallsFaced();
											DecimalFormat df = new DecimalFormat("0.0");

											print_writer
													.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
															+ "tStrikeRate" + row_id + " SET " + df.format(strike_rate)
															+ "\0");
										}
									}
								}
								if (config.getPrimaryIpAddress().equalsIgnoreCase("LOCALHOST")) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgPlayerImage" + row_id + " SET " + photo_path
											+ inn.getBatting_team().getTeamName4().toUpperCase() + centre_path
											+ inn.getBattingCard().get(b - 1).getPlayer().getPhoto()
											+ CricketUtil.PNG_EXTENSION + "\0");
								} else {
									if (!new File("\\\\" + config.getPrimaryIpAddress() + "\\c\\Images\\MPL\\Photos\\"
											+ inn.getBatting_team().getTeamName4().toUpperCase() + "\\"
											+ inn.getBattingCard().get(b - 1).getPlayer().getPhoto()
											+ CricketUtil.PNG_EXTENSION).exists()) {
										this.status = CricketUtil.UNSUCCESSFUL;
									}
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgPlayerImage" + row_id + " SET " + "\\\\\\\\"
											+ config.getPrimaryIpAddress() + local_photo_path
											+ inn.getBatting_team().getTeamName4().toUpperCase() + "\\\\"
											+ inn.getBattingCard().get(b - 1).getPlayer().getPhoto()
											+ CricketUtil.PNG_EXTENSION + "\0");
								}
							}
						}
					}
				}
			}

			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.494\0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}

