	public void populateNameSuperPlayer(PrintWriter print_writer,String viz_scene, String captainWicketKeeper, int playerId, List<Player> Plyrs, MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			this.status = CricketUtil.SUCCESSFUL;
			String Home_or_Away="";
			Player player;
			
			print_writer.println(
					"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vFlag" + " SET " + "1" + "\0");
			player = Plyrs.stream().filter(plyr -> plyr.getPlayerId() == playerId).findAny().orElse(null);
			
			if(player.getSurname() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tPlayerFirstName" + " SET " + player.getFirstname() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tPlayerLastName" + " SET " + player.getSurname() + "\0");
			}else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tPlayerFirstName" + " SET " + "" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tPlayerLastName" + " SET " +  player.getFirstname() + "\0");
			}
			
			if(player.getTeamId() == match.getSetup().getHomeTeamId()) {
				Home_or_Away = match.getSetup().getHomeTeam().getTeamName1().toUpperCase();
				
				print_writer.println(
						"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
								+ logo_path + match.getSetup().getHomeTeam().getTeamBadge()
								+ "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01"
						+ " SET " + " " + "\0");
			}
			else {
				Home_or_Away = match.getSetup().getAwayTeam().getTeamName1().toUpperCase();
				print_writer.println(
						"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
								+ logo_path + match.getSetup().getAwayTeam().getTeamBadge()
								+ "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01"
						+ " SET " + " " + "\0");
			}
			
			switch(captainWicketKeeper.toUpperCase())
			{
			case CricketUtil.CAPTAIN:
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ captainWicketKeeper.toUpperCase() + ", " + Home_or_Away + "\0");
				break;
			case CricketUtil.WICKET_KEEPER:
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ "WICKET-KEEPER" + ", " + Home_or_Away + "\0");
				break;
			case "PLAYER OF THE MATCH":
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ captainWicketKeeper.toUpperCase() + "\0");
				break;
			case "PLAYER OF THE TOURNAMENT":
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ captainWicketKeeper.toUpperCase() + "\0");
				break;
			case "PLAYER OF THE SERIES":
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ captainWicketKeeper.toUpperCase() + "\0");
				break;
			case CricketUtil.PLAYER:
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ Home_or_Away + "\0");
				break;
			case "CAPTAIN-WICKETKEEPER":
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ "CAPTAIN & WICKET-KEEPER" + ", " + Home_or_Away + "\0");
				break;
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.428\0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}

