	public void populateLTPlayerProfile(PrintWriter print_writer, String viz_scene, String Profile,
			String TypeofProfile, Statistics stats, MatchAllData match, String broadcaster)
			throws InterruptedException {
		double economy_rate = 0;

		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {

			if (stats.getStats_type().getStatsShortName().toUpperCase().equalsIgnoreCase(CricketUtil.DT20)) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSubHead" + " SET "
						+ "T20 CAREER" + "\0");
			} else if (stats.getStats_type().getStatsShortName().toUpperCase().equalsIgnoreCase(CricketUtil.IT20)) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSubHead" + " SET "
						+ "T20I CAREER" + "\0");
			} else if (stats.getStats_type().getStatsShortName().toUpperCase().equalsIgnoreCase("FBS1")) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSubHead" + " SET "
						+ "FAIRBREAK INVITATIONAL 2022" + "\0");
			} else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSubHead" + " SET "
						+ stats.getStats_type().getStatsShortName().toUpperCase() + " CAREER" + "\0");
			}

			Player plyr = getPlayerFromMatchData(stats.getPlayerID(), match);
			if (plyr.getSurname() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerFirstName"
						+ " SET " + plyr.getFirstname() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerLastName"
						+ " SET " + plyr.getSurname() + "\0");
			} else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerFirstName"
						+ " SET " + "" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerLastName"
						+ " SET " + plyr.getFirstname() + "\0");
			}
			if (plyr.getTeamId() == match.getSetup().getHomeTeamId()) {
				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
						+ logo_path + match.getSetup().getHomeTeam().getTeamBadge() + "\0");
			} else {

				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
						+ logo_path + match.getSetup().getAwayTeam().getTeamBadge() + "\0");
			}

			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead1" + " SET "
					+ "MATCHES" + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead2" + " SET "
					+ "WICKETS" + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead3" + " SET "
					+ "ECONOMY" + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead4" + " SET "
					+ "BEST" + "\0");

			System.out.println(TypeofProfile.toUpperCase());
			switch (TypeofProfile.toUpperCase()) {
			case CricketUtil.BOWLER:
				if (stats.getMatches() == 0) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue1"
							+ " SET " + "-" + "\0");
				} else {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue1"
							+ " SET " + stats.getMatches() + "\0");
				}

				if (stats.getWickets() == 0) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue2"
							+ " SET " + "-" + "\0");
				} else {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue2"
							+ " SET " + stats.getWickets() + "\0");
				}

				print_writer
						.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue3" + " SET "
								+ CricketFunctions.getEconomy(stats.getRunsConceded(), stats.getBallsBowled(), 2, "-")
								+ "\0");

				if (stats.getBestFigures().equalsIgnoreCase("0")) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue4"
							+ " SET " + "-" + "\0");
				} else {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue4"
							+ " SET " + stats.getBestFigures() + "\0");
				}
				break;
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.625\0");
			TimeUnit.MILLISECONDS.sleep(200);
			this.status = "SUCCESSFUL";
		}

	}

