	public Infobar populateInfobar(Infobar infobar, PrintWriter print_writer, String scene, MatchAllData match,
			String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Infobar's inning is null";
		} else {

			infobar = populateInfobarTeamScore(infobar, false, print_writer, match, broadcaster);
			infobar = populateVizInfobarMiddle(infobar, false, print_writer, match, broadcaster);
			infobar = populateVizInfobarTop(infobar, false, print_writer, match, broadcaster);
			infobar = populateVizInfobarRightTop(infobar, false, print_writer, match, broadcaster);
			infobar = populateVizInfobarRightBottom(infobar, false, print_writer, match, broadcaster);

			if (match.getMatch().getCurrent_speed() != null && !match.getMatch().getCurrent_speed().isEmpty()) {
				infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
			}
		}
		return infobar;
	}

	public Infobar populateInfobarTeamScore(Infobar infobar, boolean is_this_updating, PrintWriter print_writer,
			MatchAllData match, String broadcaster) {
		for (Inning inn : match.getMatch().getInning()) {
			if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
				if (is_this_updating == false) {

					infobar.setLast_speed_value(match.getMatch().getCurrent_speed());
					infobar.setLast_ball_value(String.valueOf(inn.getTotalBalls()));
					infobar.setLast_wide_value(String.valueOf(inn.getTotalWides()));
					infobar.setLast_noball_value(String.valueOf(inn.getTotalNoBalls()));

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BattingTeamGrp$TeamName$img_Team$txt_BattingTeamName*GEOM*TEXT SET "
									+ inn.getBatting_team().getTeamName4() + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BattingTeamGrp$TeamName$img_TeamOutline$txt_BattingTeamName*GEOM*TEXT SET "
									+ inn.getBatting_team().getTeamName4() + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$txt_BowlingTeamName*GEOM*TEXT SET "
									+ "vs " + inn.getBowling_team().getTeamName4() + "\0");

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BattingBadge$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path + inn.getBatting_team().getTeamBadge() + " \0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlingBadge$LogoIn$LLC_LogoGrp$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path + inn.getBowling_team().getTeamBadge() + " \0");
				}

				if (inn.getTotalWickets() >= 10) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BattingTeamGrp$TeamName$img_Text$txt_Score*GEOM*TEXT SET "
									+ inn.getTotalRuns() + "\0");
				} else {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BattingTeamGrp$TeamName$img_Text$txt_Score*GEOM*TEXT SET "
									+ inn.getTotalRuns() + slashOrDash + inn.getTotalWickets() + "\0");
				}

				print_writer.println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$txt_Overs*GEOM*TEXT SET "
								+ CricketFunctions.OverBalls(inn.getTotalOvers(), inn.getTotalBalls()) + "\0");

				if (match.getSetup().getTargetType().equalsIgnoreCase(CricketUtil.DLS)
						|| match.getSetup().getTargetType().equalsIgnoreCase(CricketUtil.VJD)) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$txt_DLS*GEOM*TEXT SET "
									+ "(" + match.getSetup().getTargetOvers() + ") "
									+ match.getSetup().getTargetType().toUpperCase() + "\0");
				} else if (match.getSetup().getTargetOvers() != null && !match.getSetup().getTargetOvers().isEmpty()) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$txt_DLS*GEOM*TEXT SET "
									+ "(" + match.getSetup().getTargetOvers() + ") " + "\0");
				} else {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$txt_DLS*GEOM*TEXT SET "
									+ " " + "\0");
				}

				if (match.getSetup().getMatchType().equalsIgnoreCase(CricketUtil.SUPER_OVER)
						&& match.getSetup().getMaxOvers() == 1) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$img_Text$txt_PowerPlay*ACTIVE SET 0 \0");
				} else {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$img_Text$txt_PowerPlay*GEOM*TEXT SET "
									+ "P" + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$ScoreGrp$BowlTeam_Over_PPGrp$img_Text1$Over_PP$img_Text$txt_PowerPlay*ACTIVE SET 1 \0");
					if (!CricketFunctions.processPowerPlay(CricketUtil.MINI, match).isEmpty()) {
						if (infobar.isPowerplay_on_screen() == true) {
							break;
						} else {
							infobar.setPowerplay_on_screen(true);
							print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*PowerPlayIn START \0");
							powerplay_on_screen = true;
						}
					} else {
						if (infobar.isPowerplay_on_screen() == true) {
							print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*PowerPlayOut START \0");
							infobar.setPowerplay_on_screen(false);
						}
					}
				}
			}
		}

		return infobar;
	}

	public Infobar populateVizInfobarMiddle(Infobar infobar, boolean is_this_updating, PrintWriter print_writer,
			MatchAllData match, String broadcaster) throws InterruptedException {
		List<BattingCard> current_batsmen = new ArrayList<BattingCard>();
		switch (infobar.getMiddle_section().toUpperCase()) {
		case CricketUtil.BATSMAN:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
					for (BattingCard bc : inn.getBattingCard()) {
						if (inn.getPartnerships() != null && inn.getPartnerships().size() > 0) {
							if (bc.getPlayerId() == inn.getPartnerships().get(inn.getPartnerships().size() - 1)
									.getFirstBatterNo()) {
								current_batsmen.add(bc);
							} else if (bc.getPlayerId() == inn.getPartnerships().get(inn.getPartnerships().size() - 1)
									.getSecondBatterNo()) {
								current_batsmen.add(bc);
							}
						}
					}

					if (infobar.getLast_batsmen() == null || infobar.getLast_batsmen().size() <= 0) {
						infobar.setLast_batsmen(current_batsmen);
					}
					populateCurrentBatsmen(infobar, print_writer, match, broadcaster, current_batsmen);

					if (is_this_updating == false) {
						processAnimation(print_writer, "Batsman1In", "START", broadcaster);
						processAnimation(print_writer, "Batsman2In", "START", broadcaster);
					}
				}
			}
			break;
		}
		return infobar;
	}

	public Infobar populateCurrentBatsmen(Infobar infobar, PrintWriter print_writer, MatchAllData match,
			String broadcaster, List<BattingCard> current_batsmen) throws InterruptedException {
		for (Inning inn : match.getMatch().getInning()) {

			if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {

				if (current_batsmen != null && current_batsmen.size() >= 1) {
					if (infobar.getLast_batsmen() != null && infobar.getLast_batsmen().size() >= 1) {
						if (infobar.getLast_batsmen().get(0).getPlayerId() != current_batsmen.get(0).getPlayerId()) {
							processAnimation(print_writer, "Batsman1Out", "START", broadcaster);
							TimeUnit.MILLISECONDS.sleep(800);

							if (CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(0).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else if (CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(0).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "0" + "\0");
							}

							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$txt_Batsman*GEOM*TEXT SET "
											+ current_batsmen.get(0).getPlayer().getTicker_name() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$ScoreGrp$txt_Runs*GEOM*TEXT SET "
											+ current_batsmen.get(0).getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$ScoreGrp$txt_Balls*GEOM*TEXT SET "
											+ current_batsmen.get(0).getBalls() + "\0");
							processAnimation(print_writer, "Batsman1In", "START", broadcaster);
							processAnimation(print_writer, "Bat1DelhighlightOut", "SHOW 0.180", broadcaster);
						} else {
							if (CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(0).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else if (CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(0).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "0" + "\0");
							}
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$txt_Batsman*GEOM*TEXT SET "
											+ current_batsmen.get(0).getPlayer().getTicker_name() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$ScoreGrp$txt_Runs*GEOM*TEXT SET "
											+ current_batsmen.get(0).getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll1$ScoreGrp$txt_Balls*GEOM*TEXT SET "
											+ current_batsmen.get(0).getBalls() + "\0");

							if (current_batsmen.get(0).getStatus().equalsIgnoreCase(CricketUtil.OUT)
									|| current_batsmen.get(0).getStatus().equalsIgnoreCase(CricketUtil.STILL_TO_BAT)) {
								processAnimation(print_writer, "Bat1DelhighlightIn", "SHOW 0.220", broadcaster);
							}
						}
						if (infobar.getLast_batsmen().get(1).getPlayerId() != current_batsmen.get(1).getPlayerId()) {
							processAnimation(print_writer, "Batsman2Out", "START", broadcaster);
							TimeUnit.MILLISECONDS.sleep(800);

							if (CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(1).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else if (CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(1).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "0" + "\0");
							}

							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$txt_Batsman*GEOM*TEXT SET "
											+ current_batsmen.get(1).getPlayer().getTicker_name() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$ScoreGrp$txt_Runs*GEOM*TEXT SET "
											+ current_batsmen.get(1).getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$ScoreGrp$txt_Balls*GEOM*TEXT SET "
											+ current_batsmen.get(1).getBalls() + "\0");
							processAnimation(print_writer, "Batsman2In", "START", broadcaster);
							processAnimation(print_writer, "Bat2DelhighlightOut", "SHOW 0.180", broadcaster);
						} else {

							if (CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(1).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else if (CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(),
									inn.getInningNumber(), current_batsmen.get(1).getPlayerId())
									.equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "0" + "\0");
							}

							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$txt_Batsman*GEOM*TEXT SET "
											+ current_batsmen.get(1).getPlayer().getTicker_name() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$ScoreGrp$txt_Runs*GEOM*TEXT SET "
											+ current_batsmen.get(1).getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$BatsmanAll2$ScoreGrp$txt_Balls*GEOM*TEXT SET "
											+ current_batsmen.get(1).getBalls() + "\0");
							if (current_batsmen.get(1).getStatus().equalsIgnoreCase(CricketUtil.OUT)
									|| current_batsmen.get(1).getStatus().equalsIgnoreCase(CricketUtil.STILL_TO_BAT)) {
								processAnimation(print_writer, "Bat2DelhighlightIn", "SHOW 0.220", broadcaster);
							}
						}
					}

					if (current_batsmen.get(0).getStatus().toUpperCase().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
						if (current_batsmen.get(0).getOnStrike().equalsIgnoreCase(CricketUtil.YES)) {
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$OnStrikeGrp$img_Text*FUNCTION*Omo*vis_con SET "
											+ "0" + " \0");
						}
					}
					if (current_batsmen.get(1).getStatus().toUpperCase().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
						if (current_batsmen.get(1).getOnStrike().equalsIgnoreCase(CricketUtil.YES)) {
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BatsmanGrp$OnStrikeGrp$img_Text*FUNCTION*Omo*vis_con SET "
											+ "1" + " \0");
						}
					}
				}
			}
		}

		infobar.setLast_batsmen(current_batsmen);
		return infobar;
	}

	public Infobar populateVizInfobarRight(Infobar infobar, boolean is_this_updating, PrintWriter print_writer,
			MatchAllData match, String broadcaster) throws InterruptedException, IOException {
		switch (infobar.getBottom_right_section().toUpperCase()) {
		case "EQUATION":
			if (CricketFunctions.GetTargetData(match).getRemaningRuns() == 0
					|| match.getMatch().getInning().get(1).getTotalWickets() >= 10
					|| CricketFunctions.GetTargetData(match).getRemaningBall() == 0) {
//				processAnimation(print_writer, "Section4$EquationOut", "START", broadcaster);
////				print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation*ACTIVE SET 0" + "\0");	
//				print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET " + 
//							CricketFunctions.GenerateMatchSummaryStatus(2, match, CricketUtil.FULL).toUpperCase() + "\0");
//				processAnimation(print_writer, "Section4$FreeTextIn", "START", broadcaster);
////				processAnimation(print_writer, "Section4$FreeTextIn", "SHOW 0.500", broadcaster);
//				infobar.setBottom_right_section("");
//				showWinner(infobar, print_writer, match);
			} else {
				print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation*ACTIVE SET 1" + "\0");
				print_writer.println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
								+ CricketFunctions.GetTargetData(match).getRemaningRuns() + "\0");

				print_writer.println(
						"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$Data1Grp$txt_Head2*GEOM*TEXT SET "
								+ "RUN" + CricketFunctions.Plural(CricketFunctions.GetTargetData(match).getRemaningRuns()).toUpperCase()
								+ "\0");

				if (!match.getSetup().getTargetOvers().equalsIgnoreCase("")) {
					if (match.getSetup().getTargetOvers().contains(".")) {

						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
										+ ((Integer.valueOf(match.getSetup().getTargetOvers().split("\\.")[0]) * 6)
												+ Integer.valueOf(match.getSetup().getTargetOvers().split("\\.")[1])
												- (match.getMatch().getInning().get(1).getTotalOvers() * 6
														+ match.getMatch().getInning().get(1).getTotalBalls()))
										+ "\0");

						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$txt_Head4*GEOM*TEXT SET "
										+ "BALL"
										+ CricketFunctions
												.Plural(((Integer
														.valueOf(match.getSetup().getTargetOvers().split("\\.")[0]) * 6)
														+ Integer.valueOf(
																match.getSetup().getTargetOvers().split("\\.")[1])
														- (match.getMatch().getInning().get(1).getTotalOvers() * 6
																+ match.getMatch().getInning().get(1).getTotalBalls())))
												.toUpperCase()
										+ "\0");

					} else {

						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
										+ ((Integer.valueOf(match.getSetup().getTargetOvers()) * 6)
												- (match.getMatch().getInning().get(1).getTotalOvers() * 6
														+ match.getMatch().getInning().get(1).getTotalBalls()))
										+ "\0");

						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$txt_Head4*GEOM*TEXT SET "
										+ "BALL"
										+ CricketFunctions
												.Plural(((Integer.valueOf(match.getSetup().getTargetOvers()) * 6)
														- (match.getMatch().getInning().get(1).getTotalOvers() * 6
																+ match.getMatch().getInning().get(1).getTotalBalls())))
												.toUpperCase()
										+ "\0");
					}
				} else {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
									+ ((match.getSetup().getMaxOvers() * 6)
											- (match.getMatch().getInning().get(1).getTotalOvers() * 6
													+ match.getMatch().getInning().get(1).getTotalBalls()))
									+ "\0");

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$Equation$DataAll$Data2Grp$txt_Head4*GEOM*TEXT SET "
									+ "BALL"
									+ CricketFunctions
											.Plural(((match.getSetup().getMaxOvers() * 6)
													- (match.getMatch().getInning().get(1).getTotalOvers() * 6
															+ match.getMatch().getInning().get(1).getTotalBalls())))
											.toUpperCase()
									+ "\0");
				}
			}
			infobar.setLast_bottom_right_section("EQUATION");
			break;
		case "EXTRAS":
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {

					if (inn.getTotalPenalties() == 0) {
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
										+ "EXTRAS - " + inn.getTotalExtras() + " (WD-" + inn.getTotalWides() + ",NB-"
										+ inn.getTotalNoBalls() + ",LB-" + inn.getTotalLegByes() + ",B-"
										+ inn.getTotalByes() + ")" + "\0");
					} else {
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
										+ "EXTRAS - " + inn.getTotalExtras() + " (WD-" + inn.getTotalWides() + ",NB-"
										+ inn.getTotalNoBalls() + ",LB-" + inn.getTotalLegByes() + ",B-"
										+ inn.getTotalByes() + ",P-" + inn.getTotalPenalties() + ")" + "\0");
					}
				}
			}
			infobar.setLast_bottom_right_section("EXTRAS");
			break;
		case "REVIEW":
			String text_to_return = "";
			int lineIndex1 = 1;
			boolean found1 = false;
			BufferedReader br = new BufferedReader(new FileReader(CricketUtil.CRICKET_DIRECTORY + "Reviews.txt"));

			while ((text_to_return = br.readLine()) != null) {
				if (lineIndex1 == 1) {
					print_writer
							.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
									+ "REVIEWS REMAINING : \n" + match.getSetup().getHomeTeam().getTeamName4() + " "
									+ text_to_return.split(" ")[0] + "              "
									+ match.getSetup().getAwayTeam().getTeamName4() + " " + text_to_return.split(" ")[1]
									+ "\0");

					found1 = true;
					break;
				}
				lineIndex1++;
			}
			if (!found1) {
				// System.out.println("Line Not There");
			}
			infobar.setLast_bottom_right_section("REVIEW");
			break;
		case CricketUtil.DOT:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer
							.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$DotBalls$txt_Head*GEOM*TEXT SET "
									+ "DOTS THIS  INNINGS" + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$DotBalls$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ CricketFunctions.getScoreTypeData(CricketUtil.TEAM, match, inn.getInningNumber(),
											0, ",", match.getEventFile().getEvents()).split(",")[0]
									+ "\0");
				}
			}
			infobar.setLast_bottom_right_section(CricketUtil.DOT);
			break;
		case CricketUtil.FOUR:

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$TournamentFours$txt_Head*GEOM*TEXT SET "
									+ "FOURS THIS INNINGS" + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$TournamentFours$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ inn.getTotalFours() + "\0");
				}
			}
			infobar.setLast_bottom_right_section(CricketUtil.FOUR);
			break;
		case CricketUtil.SIX:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$TournamentSixes$txt_Head*GEOM*TEXT SET "
									+ "SIXES THIS INNINGS" + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$TournamentSixes$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ inn.getTotalSixes() + "\0");
				}
			}
			infobar.setLast_bottom_right_section(CricketUtil.SIX);
			break;
		case CricketUtil.COMPARE:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == 2 && inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$AtThisStage$txt_Head*GEOM*TEXT SET "
									+ "AFTER " + CricketFunctions.OverBalls(inn.getTotalOvers(), inn.getTotalBalls())
									+ " OVERS" + "\0");

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$AtThisStage$DataAll$Data1Grp$txt_Head2*GEOM*TEXT SET "
									+ inn.getBowling_team().getTeamName4().toUpperCase() + " WERE" + "\0");

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$AtThisStage$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ CricketFunctions.compareInningData(match, "-", 1,
											match.getEventFile().getEvents())
									+ "\0");
				}
			}
			infobar.setLast_bottom_right_section(CricketUtil.COMPARE);
			break;
		case CricketUtil.BOUNDARY:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$BallsSince$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ CricketFunctions.lastFewOversData(CricketUtil.BOUNDARY,
											match.getEventFile().getEvents(), inn.getInningNumber())
									+ "\0");
				}
			}
			infobar.setLast_bottom_right_section(CricketUtil.BOUNDARY);
			break;
		case "PROJECTED":
			String[] proj_score_rate = new String[CricketFunctions.projectedScore(match).size()];
			for (int i = 0; i < CricketFunctions.projectedScore(match).size(); i++) {
				proj_score_rate[i] = CricketFunctions.projectedScore(match).get(i);
			}
			print_writer
					.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$ProjectedScore$txt_Head*GEOM*TEXT SET "
							+ "PROJECTED SCORES" + "\0");

			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$ProjectedScore$DataAll$Data1Grp$txt_Head2*GEOM*TEXT SET "
							+ "@CRR (" + proj_score_rate[0] + ")" + "\0");
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$ProjectedScore$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
							+ proj_score_rate[1] + "\0");
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$ProjectedScore$DataAll$Data2Grp$txt_Head3*GEOM*TEXT SET "
							+ "@" + proj_score_rate[2] + "\0");
			print_writer.println(
					"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$ProjectedScore$DataAll$Data2Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
							+ proj_score_rate[3] + "\0");

			infobar.setLast_bottom_right_section(CricketUtil.PROJECTED);
			break;
		case "BOUNDARIES":
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$InningBoundaries$txt_Head*GEOM*TEXT SET "
									+ "INNINGS BOUNDARIES" + "\0");

					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$InningBoundaries$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
									+ inn.getTotalFours() + "\0");
					print_writer.println(
							"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$InningBoundaries$Data2Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
									+ inn.getTotalSixes() + "\0");

				}
			}

			infobar.setLast_bottom_right_section("BOUNDARIES");
			break;
		case "LAST_WICKET":
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().equalsIgnoreCase(CricketUtil.YES)) {
					for (BattingCard bc : inn.getBattingCard()) {
						if (inn.getFallsOfWickets() != null && !inn.getFallsOfWickets().isEmpty()) {
							if (inn.getFallsOfWickets().size() > 0) {
								if (inn.getFallsOfWickets().get(inn.getFallsOfWickets().size() - 1)
										.getFowPlayerID() == bc.getPlayerId()) {
									print_writer.println(
											"-1 RENDERER*TREE*$Main$All$Section4$LastWicket$DataAll*ACTIVE SET 1 \0");
									print_writer.println(
											"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$LastWicket$txt_Head*GEOM*TEXT SET "
													+ "LAST WICKET" + "\0");
									print_writer.println(
											"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$LastWicket$DataAll$Data1Grp$txt_Head2*GEOM*TEXT SET "
													+ bc.getPlayer().getTicker_name() + "\0");
									print_writer.println(
											"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$LastWicket$DataAll$Data1Grp$Data$img_Text2$txt_Data1*GEOM*TEXT SET "
													+ bc.getRuns() + "\0");
									print_writer.println(
											"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$LastWicket$DataAll$Data1Grp$Data$img_Text2$txt_Data2*GEOM*TEXT SET "
													+ bc.getBalls() + "\0");
								}
							}
						} else {
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$LastWicket$txt_Head*GEOM*TEXT SET "
											+ "LAST WICKET" + "\0");
							print_writer
									.println("-1 RENDERER*TREE*$Main$All$Section4$LastWicket$DataAll*ACTIVE SET 0 \0");
						}
					}
				}
			}
			infobar.setLast_bottom_right_section("LAST_WICKET");
			break;
		case "TOURNAMENT-NAME":
			print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section4$FreeText$txt_Head*GEOM*TEXT SET "
					+ match.getSetup().getTournament() + "\0");
			infobar.setLast_bottom_right_section("TOURNAMENT-NAME");
			break;
		}

		return infobar;
	}

	public Infobar populateVizInfobarRightTop(Infobar infobar, boolean is_this_updating, PrintWriter print_writer,
			MatchAllData match, String broadcaster) throws InterruptedException {

		switch (infobar.getBottom_right_top_section().toUpperCase()) {
		case CricketUtil.BOWLER:
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
					for (BowlingCard boc : inn.getBowlingCard()) {
						if (boc.getStatus().toUpperCase().equalsIgnoreCase("CURRENTBOWLER")
								|| boc.getStatus().toUpperCase().equalsIgnoreCase("LASTBOWLER")) {
							if (infobar.getLast_bowler() == null
									|| infobar.getLast_bowler().getPlayerId() != boc.getPlayerId()) {
								processAnimation(print_writer, "BowlerOut", "START", broadcaster);
								processAnimation(print_writer, "Section3Out", "START", broadcaster);
								TimeUnit.SECONDS.sleep(1);
							}

							if (CricketFunctions.checkImpactPlayer(match.getEventFile().getEvents(),
									inn.getInningNumber(), boc.getPlayerId()).equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else if (CricketFunctions.checkImpactPlayerBowler(match.getEventFile().getEvents(),
									inn.getInningNumber(), boc.getPlayerId()).equalsIgnoreCase(CricketUtil.YES)) {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "1" + "\0");
							} else {
								print_writer.println(
										"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$Select_Impact*FUNCTION*Omo*vis_con SET "
												+ "0" + "\0");
							}

							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$txt_Bowler*GEOM*TEXT SET "
											+ boc.getPlayer().getTicker_name() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$BowlingDataGrp$txt_Figures*GEOM*TEXT SET "
											+ boc.getWickets() + slashOrDash + boc.getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$BowlerGrp$Bowler$BowlingDataGrp$txt_Overs*GEOM*TEXT SET "
											+ CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + "\0");

							if (infobar.getLast_bowler() == null
									|| infobar.getLast_bowler().getPlayerId() != boc.getPlayerId()) {
								processAnimation(print_writer, "BowlerIn", "START", broadcaster);
								if (infobar.getLast_bottom_right_bottom_section() != null
										&& !infobar.getLast_bottom_right_bottom_section().trim().isEmpty()) {
									if (infobar.getLast_bottom_right_bottom_section()
											.equalsIgnoreCase(CricketUtil.OVER)) {
										processAnimation(print_writer, "Section3$ThisOverIn", "SHOW 0.520",
												broadcaster);
										processAnimation(print_writer, "Section3$FreeTextIn", "SHOW 0.0", broadcaster);
									}
								}
								processAnimation(print_writer, "Section3In", "START", broadcaster);
							}
							infobar.setLast_bowler(boc);
							infobar.setLast_bottom_right_top_section(CricketUtil.BOWLER);
						}
					}
				}
			}
			break;
		}
		return infobar;
	}

