	public Infobar populateSection5(Infobar infobar, boolean is_this_updating, PrintWriter print_writer, int Line_value,
			MatchAllData match, String broadcaster) throws IOException {

		switch (infobar.getFull_section().toUpperCase()) {
		case "FREETEXT":
			String text_to_return = "";
			int lineIndex1 = 1;
			boolean found1 = false;
			BufferedReader br = new BufferedReader(
					new FileReader(CricketUtil.CRICKET_DIRECTORY + CricketUtil.INFOBAR_FREE_TXT));

			while ((text_to_return = br.readLine()) != null) {
				if (lineIndex1 == Line_value) {
					if (Line_value == 1) {
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$FreeText*FUNCTION*Omo*vis_con SET 0 \0");
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$FreeText$txt_Head*GEOM*TEXT SET "
										+ text_to_return + "\0");
					} else if (Line_value == 2) {
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$FreeText*FUNCTION*Omo*vis_con SET 1 \0");
						print_writer.println(
								"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$FreeText$txt_Head2*GEOM*TEXT SET "
										+ text_to_return + "\0");
					}
					found1 = true;
					break;
				}
				lineIndex1++;
			}
			if (!found1) {
				// System.out.println("Line Not There");
			}

			break;
		case "TIMELINE":
			String this_ball_data = "";
			int ball_count = 0;

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getIsCurrentInning().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {

					if (is_this_updating == false) {
						for (int a = 1; a <= 25; a++) {
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
											+ a + "*ACTIVE SET 0\0");
						}
					}

//					if(((inn.getTotalOvers()*6) + inn.getTotalBalls()) > 22) {
//						print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vTimeline" + " SET " + "22" + "\0");
//					}
//					else {
//						print_writer.println("-1 RENDERER*FRONT_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vTimeline" + " SET " 
//											+ ((inn.getTotalOvers()*6) + inn.getTotalBalls()) + "\0");
//					}

					if ((match.getEventFile().getEvents() != null) && (match.getEventFile().getEvents().size() > 0)) {
						for (int i = match.getEventFile().getEvents().size() - 1; i >= 0; i--) {
							if (inn.getInningNumber() == match.getEventFile().getEvents().get(i)
									.getEventInningNumber()) {
								switch (match.getEventFile().getEvents().get(i).getEventType()) {
								case CricketUtil.CHANGE_BOWLER:
								case CricketUtil.ONE:
								case CricketUtil.TWO:
								case CricketUtil.THREE:
								case CricketUtil.FIVE:
								case CricketUtil.DOT:
								case CricketUtil.FOUR:
								case CricketUtil.SIX:
								case CricketUtil.WIDE:
								case CricketUtil.NO_BALL:
								case CricketUtil.BYE:
								case CricketUtil.LEG_BYE:
								case CricketUtil.PENALTY:
								case CricketUtil.LOG_ANY_BALL:
								case CricketUtil.LOG_WICKET:

									if (match.getEventFile().getEvents().get(i).getEventType()
											.equalsIgnoreCase(CricketUtil.LOG_WICKET)) {
										if (!match.getEventFile().getEvents().get(i).getEventHowOut()
												.equalsIgnoreCase(CricketUtil.RETIRED_HURT)
												&& !match.getEventFile().getEvents().get(i).getEventHowOut()
														.equalsIgnoreCase(CricketUtil.ABSENT_HURT)) {

											ball_count = ball_count + 1;
										}
									} else {
										ball_count = ball_count + 1;
									}

									print_writer.println(
											"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
													+ ball_count + "*ACTIVE SET 1\0");

									switch (match.getEventFile().getEvents().get(i).getEventType()) {
									case CricketUtil.CHANGE_BOWLER:

										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 0 \0");
										break;
									case CricketUtil.DOT:
										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 1 \0");
										break;
									case CricketUtil.ONE:
									case CricketUtil.TWO:
									case CricketUtil.THREE:
									case CricketUtil.FIVE:

										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 2 \0");
										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count
														+ "$SelectType$Runs$img_Text2$txt_Ball*GEOM*TEXT SET "
														+ match.getEventFile().getEvents().get(i).getEventRuns()
														+ "\0");
										break;
									case CricketUtil.FOUR:
									case CricketUtil.SIX:

										if (match.getEventFile().getEvents().get(i).getEventWasABoundary() != null
												&& match.getEventFile().getEvents().get(i).getEventWasABoundary()
														.equalsIgnoreCase(CricketUtil.YES)) {
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 4 \0");
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count
															+ "$SelectType$Fours_Six_Wickets$img_Text2$txt_Ball*GEOM*TEXT SET "
															+ match.getEventFile().getEvents().get(i).getEventRuns()
															+ "\0");
										} else {
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 2 \0");
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count
															+ "$SelectType$Runs$img_Text2$txt_Ball*GEOM*TEXT SET "
															+ match.getEventFile().getEvents().get(i).getEventRuns()
															+ "\0");
										}
										break;
									case CricketUtil.WIDE:
									case CricketUtil.NO_BALL:
									case CricketUtil.BYE:
									case CricketUtil.LEG_BYE:
									case CricketUtil.PENALTY:
										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 3 \0");
										if (match.getEventFile().getEvents().get(i).getEventType()
												.equalsIgnoreCase(CricketUtil.WIDE)) {
											this_ball_data = "WD";
										} else if (match.getEventFile().getEvents().get(i).getEventType()
												.equalsIgnoreCase(CricketUtil.NO_BALL)) {
											this_ball_data = "NB";
										} else if (match.getEventFile().getEvents().get(i).getEventType()
												.equalsIgnoreCase(CricketUtil.LEG_BYE)) {
											this_ball_data = "LB";
										} else if (match.getEventFile().getEvents().get(i).getEventType()
												.equalsIgnoreCase(CricketUtil.BYE)) {
											this_ball_data = "B";
										} else if (match.getEventFile().getEvents().get(i).getEventType()
												.equalsIgnoreCase(CricketUtil.PENALTY)) {
											this_ball_data = "P";
										}

										int runs = match.getEventFile().getEvents().get(i).getEventRuns()
												+ match.getEventFile().getEvents().get(i).getEventSubExtraRuns();

										if (runs > 1) {
											this_ball_data = String.valueOf(runs) + this_ball_data.toUpperCase();
										} else {
											this_ball_data = this_ball_data.toUpperCase();
										}

										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count
														+ "$SelectType$Rest$img_Text2$txt_Ball*GEOM*TEXT SET "
														+ this_ball_data + "\0");

										break;
									case CricketUtil.LOG_WICKET:
										if (match.getEventFile().getEvents().get(i).getEventHowOut()
												.equalsIgnoreCase(CricketUtil.RETIRED_HURT)) {
											ball_count = ball_count - 1;
											break;
										} else {
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 4 \0");

											if (match.getEventFile().getEvents().get(i).getEventRuns() > 0) {
												print_writer.println(
														"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
																+ ball_count
																+ "$SelectType$Fours_Six_Wickets$txt_Ball*GEOM*TEXT SET "
																+ String.valueOf(match.getEventFile().getEvents().get(i)
																		.getEventRuns())
																+ "+W" + "\0");
											} else {
												print_writer.println(
														"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
																+ ball_count
																+ "$SelectType$Fours_Six_Wickets$txt_Ball*GEOM*TEXT SET "
																+ "W" + "\0");
											}
										}
										break;
									case CricketUtil.LOG_ANY_BALL:
										print_writer.println(
												"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
														+ ball_count + "$SelectType*FUNCTION*Omo*vis_con SET 3 \0");
										if (match.getEventFile().getEvents().get(i).getEventSubExtra()
												.equalsIgnoreCase(CricketUtil.PENALTY)) {
											this_ball_data = String.valueOf(
													match.getEventFile().getEvents().get(i).getEventSubExtraRuns())
													+ "PN";
											print_writer.println(
													"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
															+ ball_count
															+ "$SelectType$Rest$img_Text2$txt_Ball*GEOM*TEXT SET "
															+ this_ball_data + "\0");
										} else {
											if (match.getEventFile().getEvents().get(i).getEventExtra() != null
													&& !match.getEventFile().getEvents().get(i).getEventExtra()
															.isEmpty()) {
												if (match.getEventFile().getEvents().get(i).getEventExtra()
														.equalsIgnoreCase(CricketUtil.WIDE)) {
													if (match.getEventFile().getEvents().get(i).getEventSubExtra()
															.equalsIgnoreCase(CricketUtil.WIDE)) {
														if ((match.getEventFile().getEvents().get(i).getEventRuns()
																+ match.getEventFile().getEvents().get(i)
																		.getEventExtraRuns()
																+ match.getEventFile().getEvents().get(i)
																		.getEventSubExtraRuns()) > 1) {
															this_ball_data = String.valueOf(match.getEventFile()
																	.getEvents().get(i).getEventRuns()
																	+ match.getEventFile().getEvents().get(i)
																			.getEventExtraRuns()
																	+ match.getEventFile().getEvents().get(i)
																			.getEventSubExtraRuns())
																	+ "WD";
														} else {
															this_ball_data = "WD";
														}

													} else {
														this_ball_data = String.valueOf(
																match.getEventFile().getEvents().get(i).getEventRuns()
																		+ match.getEventFile().getEvents().get(i)
																				.getEventExtraRuns())
																+ "WD";
													}
												} else if (match.getEventFile().getEvents().get(i).getEventExtra()
														.equalsIgnoreCase(CricketUtil.NO_BALL)) {
													if (match.getEventFile().getEvents().get(i).getEventRuns() > 0) {
														this_ball_data = "NB" + "+" + match.getEventFile().getEvents()
																.get(i).getEventRuns();
													} else {
														this_ball_data = "NB";
													}
												} else {
													if (match.getEventFile().getEvents().get(i).getEventRuns() > 0) {
														this_ball_data = String.valueOf(
																match.getEventFile().getEvents().get(i).getEventRuns());
													}
												}
											}

											if (match.getEventFile().getEvents().get(i).getEventSubExtra() != null
													&& !match.getEventFile().getEvents().get(i).getEventSubExtra()
															.isEmpty()) {
												if (!match.getEventFile().getEvents().get(i).getEventSubExtra()
														.equalsIgnoreCase(CricketUtil.WIDE)) {
													if (this_ball_data.isEmpty()) {
														this_ball_data = String.valueOf(match.getEventFile().getEvents()
																.get(i).getEventSubExtraRuns());
													} else {
														this_ball_data = this_ball_data + "+" + match.getEventFile()
																.getEvents().get(i).getEventSubExtraRuns();
													}
													if (match.getEventFile().getEvents().get(i).getEventSubExtra()
															.equalsIgnoreCase(CricketUtil.NO_BALL)) {
														this_ball_data = this_ball_data + "NB";
													} else if (match.getEventFile().getEvents().get(i)
															.getEventSubExtra().equalsIgnoreCase(CricketUtil.LEG_BYE)) {
														this_ball_data = this_ball_data + "LB";

													} else if (match.getEventFile().getEvents().get(i)
															.getEventSubExtra().equalsIgnoreCase(CricketUtil.BYE)) {
														this_ball_data = this_ball_data + "B";
													} // else
														// if(match.getEvents().get(i).getEventSubExtra().equalsIgnoreCase(CricketUtil.PENALTY))
														// {
														// System.out.println("HELLO8");
														// this_ball_data = this_ball_data + "Pn";
														// }
												}
											}
											if (match.getEventFile().getEvents().get(i).getEventHowOut() != null
													&& !match.getEventFile().getEvents().get(i).getEventHowOut()
															.isEmpty()) {
												this_ball_data = this_ball_data + "+W";
												print_writer.println(
														"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
																+ ball_count
																+ "$SelectType$Rest$img_Text2$txt_Ball*GEOM*TEXT SET "
																+ this_ball_data + "\0");
											} else {
												print_writer.println(
														"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
																+ ball_count
																+ "$SelectType$Rest$img_Text2$txt_Ball*GEOM*TEXT SET "
																+ this_ball_data + "\0");
											}
										}
										break;
									}
									break;
								}
							}

							if (ball_count >= 25) {
								break;
							}

						}

						if (ball_count <= 25) {
							print_writer.println(
									"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section5$TimeLine$ThisOver$ThisOverAll$BallGrp"
											+ ball_count + "*ACTIVE SET 0\0");
						}

					}
				}
			}
			break;
		}
		infobar.setLast_full_section(infobar.getFull_section().toUpperCase());
		return infobar;
	}

	public void populateMatchPromo(PrintWriter print_writer, String viz_sence_path, int match_number, List<Team> team,
			List<Fixture> fix, MatchAllData match, String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: MatchPromo's inning is null";
		} else {

			String match_name = "", newDate = "", Date = "";

			String[] dateSuffix = { "th", "st", "nd", "rd", "th", "th", "th", "th", "th", "th",

					"th", "th", "th", "th", "th", "th", "th", "th", "th", "th",

					"th", "st", "nd", "rd", "th", "th", "th", "th", "th", "th",

					"th", "st" };

			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSumSubHeader"
					+ " SET " + match.getSetup().getTournament() + "\0");

			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo"
					+ " SET " + "FROM " + match.getSetup().getVenueName().toUpperCase() + "\0");

			for (Team TM : team) {
				if (fix.get(match_number - 1).getHometeamid() == TM.getTeamId()) {
					print_writer.println(
							"-1 RENDERER*BACK_LAYER*TREE*$Main$AllGrp$BG_ALL$All$Worm$TeamsAll$TeamDataData$logos$HomeLogoGrp$LogoMasked$TeamLogo1*TEXTURE*IMAGE SET "
									+ logo_path + TM.getTeamBadge() + " \0");
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "lgTeamLogo1" + " SET " + logo_path + TM.getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHomeTeamName" + " SET " + TM.getTeamName1().toUpperCase() + "\0");
				}
				if (fix.get(match_number - 1).getAwayteamid() == TM.getTeamId()) {
					print_writer.println(
							"-1 RENDERER*BACK_LAYER*TREE*$Main$AllGrp$BG_ALL$All$Worm$TeamsAll$TeamDataData$logos$AwayLogoGrp$LogoMasked$TeamLogo1*TEXTURE*IMAGE SET "
									+ logo_path + TM.getTeamName4().toUpperCase() + " \0");
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "lgTeamLogo2" + " SET " + logo_path + TM.getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tAwayTeamName" + " SET " + TM.getTeamName1().toUpperCase() + "\0");
				}
			}

			if (match_number < 10) {
				match_name = "MATCH " + match_number;
			} else {
				match_name = fix.get(match_number - 1).getMatchfilename().toUpperCase();
			}

			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader2"
					+ " SET " + match_name + "\0");

			Calendar cal = Calendar.getInstance();
			cal.add(Calendar.DATE, +1);
			if (fix.get(match_number - 1).getDate()
					.equalsIgnoreCase(new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime()))) {

				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader1"
						+ " SET " + "TOMORROW" + "\0");

			} else {
				cal.add(Calendar.DATE, -1);

				Date = new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());
				if (fix.get(match_number - 1).getDate().equalsIgnoreCase(Date)) {
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHeader1" + " SET " + "UP NEXT - " + fix.get(match_number - 1).getLocalTime() + "\0");

				} else {
					newDate = fix.get(match_number - 1).getDate().split("-")[0];
					if (Integer.valueOf(newDate) < 10) {
						newDate = newDate.replaceFirst("0", "");
					}

					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHeader1" + " SET " + newDate + dateSuffix[Integer.valueOf(newDate)] + " "
							+ Month.of(Integer.valueOf(fix.get(match_number - 1).getDate().split("-")[1])) + " - "
							+ fix.get(match_number - 1).getLocalTime() + "\0");
				}
			}

			print_writer.println(
					"-1 RENDERER PREVIEW SCENE*" + viz_sence_path + " C:/Temp/Preview.png In 3.543 In$DataIn 2.850 \0");
			TimeUnit.SECONDS.sleep(2);

		}
	}

