	public void populateProjectedScore(PrintWriter print_writer, String viz_scene, MatchAllData match,
			String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: ProjectedScore's inning is null";
		} else {

			String[] proj_score_rate = new String[CricketFunctions.projectedScore(match).size()];
			for (int i = 0; i < CricketFunctions.projectedScore(match).size(); i++) {
				proj_score_rate[i] = CricketFunctions.projectedScore(match).get(i);
			}

			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSubHead" + " SET "
					+ "PROJECTED SCORES" + "\0");

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == 1 & inn.getIsCurrentInning().equalsIgnoreCase("YES")) {
					print_writer
							.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
									+ logo_path + inn.getBatting_team().getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tTeamName"
							+ " SET " + inn.getBatting_team().getTeamName1().toUpperCase() + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead1"
							+ " SET " + "@" + proj_score_rate[0] + " (CRR)" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue1"
							+ " SET " + proj_score_rate[1] + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead2"
							+ " SET " + "@" + proj_score_rate[2] + " RPO" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue2"
							+ " SET " + proj_score_rate[3] + "\0");

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatHead3"
							+ " SET " + "@" + proj_score_rate[4] + " RPO" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStatValue3"
							+ " SET " + proj_score_rate[5] + "\0");

				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.625 \0");
			TimeUnit.MILLISECONDS.sleep(200);
		}

	}

	public void populateTarget(PrintWriter print_writer, String viz_scene, MatchAllData match, String broadcaster,
			Configuration config) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Target's inning is null";
		} else {
			this.status = CricketUtil.SUCCESSFUL;

			String type = "";
			for (Inning inn : match.getMatch().getInning()) {

				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
						+ logo_path + "TLogo" + "\0");

				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader" + " SET "
						+ "TARGET - " + match.getMatch().getInning().get(1).getBatting_team().getTeamName1() + "\0");

				if (match.getSetup().getTargetType().toUpperCase().equalsIgnoreCase("VJD")) {
					type = " (VJD)";
				} else if (match.getSetup().getTargetType().toUpperCase().equalsIgnoreCase("DLS")) {
					type = " (DLS)";
				} else {
					type = "";
				}

				if (match.getSetup().getTargetOvers() == null || match.getSetup().getTargetOvers().trim().isEmpty()
						&& match.getSetup().getTargetRuns() == 0) {

					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo" + " SET "
							+ "NEED " + CricketFunctions.GetTargetData(match).getTargetRuns() + " RUN"
							+ CricketFunctions.Plural(CricketFunctions.GetTargetData(match).getTargetRuns()).toUpperCase() + " FROM "
							+ match.getSetup().getMaxOvers() * 6 + " BALL"
							+ CricketFunctions.Plural(match.getSetup().getMaxOvers() * 6).toUpperCase() + type + "\0");

				} else {
					if (Double.valueOf(match.getSetup().getTargetOvers()) != 0) {
						print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo"
								+ " SET " + "NEED " + CricketFunctions.GetTargetData(match).getTargetRuns() + " RUN"
								+ CricketFunctions.Plural(CricketFunctions.GetTargetData(match).getTargetRuns()).toUpperCase()
								+ " FROM " + Integer.valueOf(match.getSetup().getTargetOvers()) * 6 + " BALL"
								+ CricketFunctions.Plural(Integer.valueOf(match.getSetup().getTargetOvers()) * 6)
										.toUpperCase()
								+ type + "\0");
					}
				}
			}
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.428 \0");
		TimeUnit.MILLISECONDS.sleep(200);
	}

