	public void populateBowlerStyle(PrintWriter print_writer, String viz_scene, int whichInning, int playerId,
			List<Player> plyr, List<Team> team, List<Ground> ground, MatchAllData match, String broadcaster)
			throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {

			print_writer.println(
					"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vFlag" + " SET " + "1" + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$LogoGrp$TeamLogo1*TEXTURE*IMAGE SET "
					+ logo_path + team.get(plyr.get(playerId - 1).getTeamId() - 1).getTeamBadge() + "\0");

			print_writer.println(
					"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo01" + " SET " + "" + "\0");

			if (plyr.get(playerId - 1).getBowlingStyle() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET "
						+ CricketFunctions.getbowlingstyle(plyr.get(playerId - 1).getBowlingStyle()).toUpperCase()
						+ "\0");
			} else {
				print_writer.println(
						"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo02" + " SET " + "" + "\0");
			}

			if (plyr.get(playerId - 1).getSurname() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerFirstName"
						+ " SET " + plyr.get(playerId - 1).getFirstname() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerLastName"
						+ " SET " + plyr.get(playerId - 1).getSurname() + "\0");
			} else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerFirstName"
						+ " SET " + "" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tPlayerLastName"
						+ " SET " + plyr.get(playerId - 1).getFirstname() + "\0");
			}

			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.428\0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}

	public void populateTieIdDouble(PrintWriter print_writer, String viz_sence_path, String day, List<Fixture> fix,
			List<Team> team, MatchAllData match, String selectedbroadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			int row_id = 1, row = 1;
			String Date = "", match_name = "", newDate = "";

			Calendar cal = Calendar.getInstance();

			String[] dateSuffix = { "th", "st", "nd", "rd", "th", "th", "th", "th", "th", "th",

					"th", "th", "th", "th", "th", "th", "th", "th", "th", "th",

					"th", "st", "nd", "rd", "th", "th", "th", "th", "th", "th",

					"th", "st" };

			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader1"
					+ " SET " + "" + "\0");

			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader1"
					+ " SET " + "" + "\0");

			if (day.toUpperCase().equalsIgnoreCase("TODAY")) {
				Date = new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader2"
						+ " SET " + "TODAY'S MATCHES " + "\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tSumSubHeader" + " SET " + "LIVE FROM " + match.getSetup().getVenueName() + "\0");
			} else if (day.toUpperCase().equalsIgnoreCase("TOMORROW")) {
				cal.add(Calendar.DATE, +1);
				Date = new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader2"
						+ " SET " + "TOMORROW'S MATCHES " + "\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tSumSubHeader" + " SET " + "LIVE FROM " + match.getSetup().getVenueName() + "\0");
			} else if (day.toUpperCase().equalsIgnoreCase("DAY_AFTER_TOMORROW")) {
				cal.add(Calendar.DATE, +2);
				Date = new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());

				newDate = Date.split("-")[0];
				if (Integer.valueOf(newDate) < 10) {
					newDate = newDate.replaceFirst("0", "");
				}

				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader2"
						+ " SET " + newDate + dateSuffix[Integer.valueOf(newDate)] + " "
						+ Month.of(Integer.valueOf(Date.split("-")[1])) + "\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
						+ "tSumSubHeader" + " SET " + "LIVE FROM " + match.getSetup().getVenueName() + "\0");
			}

			for (int i = 0; i <= fix.size() - 1; i++) {
				if (fix.get(i).getDate().equalsIgnoreCase(Date)) {
					print_writer.println(
							"-1 RENDERER*BACK_LAYER*TREE*$Main$AllGrp$All$AllDataGrp$TeamsAll$TeamDataData$Match"
									+ row_id + "_Grp$HomeLogoGrp$LogoMasked$TeamLogo1*TEXTURE*IMAGE SET " + logo_path
									+ team.get(fix.get(i).getHometeamid() - 1).getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tHomeTeamName0" + row_id + " SET "
							+ team.get(fix.get(i).getHometeamid() - 1).getTeamName1().toUpperCase() + "\0");

					if (day.toUpperCase().equalsIgnoreCase("TODAY")) {
						if (fix.get(i).getMatchnumber() < 10) {
							match_name = "MATCH " + fix.get(i).getMatchnumber();
						} else {
							match_name = fix.get(i).getMatchfilename();
						}
						print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
								+ "tInfoMatch" + row + " SET " + match_name + "\0");
					} else if (day.toUpperCase().equalsIgnoreCase("TOMORROW")
							|| day.toUpperCase().equalsIgnoreCase("DAY_AFTER_TOMORROW")) {
						if (fix.get(i).getMatchnumber() < 10) {
							match_name = "MATCH " + fix.get(i).getMatchnumber();
						} else {
							match_name = fix.get(i).getMatchfilename();
						}
						if (fix.get(i).getLocalTime() == null) {
							print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
									+ "tInfoMatch" + row + " SET " + match_name + "\0");
						} else {
							print_writer.println(
									"-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfoMatch"
											+ row + " SET " + match_name + " - " + fix.get(i).getLocalTime() + "\0");
						}
					}

					print_writer.println(
							"-1 RENDERER*BACK_LAYER*TREE*$Main$AllGrp$All$AllDataGrp$TeamsAll$TeamDataData$Match"
									+ row_id + "_Grp$AwayLogoGrp$LogoMasked$TeamLogo1*TEXTURE*IMAGE SET " + logo_path
									+ team.get(fix.get(i).getAwayteamid() - 1).getTeamBadge() + "\0");

					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tAwayTeamName0" + row_id + " SET "
							+ team.get(fix.get(i).getAwayteamid() - 1).getTeamName1().toUpperCase() + "\0");

					row_id = row_id + 1;
					row = row + 1;
				}
			}

			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_sence_path
					+ " C:/Temp/Preview.png In 3.543 In$Double_ID 3.400 In$DataIn 1.400 \0");

		}

	}

