	public void populateLtManhattan(PrintWriter print_writer, String viz_scene, int whichInning, MatchAllData match,
			String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (whichInning == 0) {
			this.status = "ERROR: Inning is null";
		} else {

			int maxRuns = 0, runsIncr = 0;
			double lngth = 0;

			for (int j = 1; j <= match.getSetup().getMaxOvers(); j++) {
				if (j < CricketFunctions
						.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).size()) {
					// if(CricketFunctions.getOverByOverData(match, whichInning,"MANHATTAN"
					// ,match.getEvents()).get(j).getInningNumber() == whichInning) {
					if (Integer.valueOf(CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalRuns()) > maxRuns) {
						maxRuns = Integer.valueOf(CricketFunctions
								.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents())
								.get(j).getOverTotalRuns()); // 33 runs came off 34th over
					}

					while (maxRuns % 3 != 0) { // 3 label in y-axis
						maxRuns = maxRuns + 1; // keep incrementing till max runs is divisible by 3. maxRuns = 35
					}
					// }
				}
			}

			for (int i = 0; i < 3; i++) {
				runsIncr = maxRuns / 3; // 35/5=7 -> Y axis will be plot like 6,12,18,24,30 & 36
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tRuns" + (3 - i)
						+ " SET " + runsIncr * (i + 1) + "\0");
			}

			for (int j = 1; j <= match.getSetup().getMaxOvers(); j++) {

				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vWkt" + (j) + " SET "
						+ "0" + "\0");

				if (j < CricketFunctions
						.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).size()) {
//					System.out.println(j + "= " + CricketFunctions.getOverByOverData(match, whichInning,"MANHATTAN" ,match.getEvents()).get(j).getOverTotalRuns());
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$BarAll*FUNCTION*Grid*num_col SET "
									+ (j) + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$Wickets*FUNCTION*Grid*num_col SET "
									+ (j) + "\0");
//					*BarValues*BarMax SET
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$All$Mann$Man20$BarGrp$BarAll*FUNCTION*BarValues*BarMax SET "
									+ "35.5" + "\0");
					lngth = ((25 * Integer.valueOf(CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalRuns())) / maxRuns); // 32 is max value of each bar
//					lngth = (CricketFunctions.getOverByOverData(match, whichInning,"MANHATTAN" ,match.getEvents()).get(j).getOverTotalRuns()/25);
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$All$Mann$Man20$BarGrp$BarAll*FUNCTION*BarValues*Bar_Value__"
									+ (j) + " SET " + lngth + "\0");

//					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBar" + (j) + " SET " + lngth + "\0");

					if (CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalWickets() > 0) {

						print_writer
								.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "vWkt" + (j)
												+ " SET "
												+ Integer.valueOf(CricketFunctions
														.getOverByOverData(match, whichInning, "MANHATTAN",
																match.getEventFile().getEvents())
														.get(j).getOverTotalWickets())
												+ "\0");
					}
				}
			}
		}
		print_writer
				.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 2.060 In$DataIn 1.536 \0");
		TimeUnit.SECONDS.sleep(1);
	}

