	public void populateBatGriff(PrintWriter print_writer, String viz_scene, int whichinning, int playerId,
			List<MatchAllData> all_matches, CricketService cricketService, MatchAllData match,
			String session_selected_broadcaster) throws InterruptedException {
		Player player = cricketService.getAllPlayer().stream().filter(plyr ->plyr.getPlayerId() == playerId).findAny().orElse(null);
		List<BatBallGriff> griff = new ArrayList<BatBallGriff>();
		String cont_name = "";
		int omo_num = 0;
		int row = 0;
		switch (session_selected_broadcaster.toUpperCase()) {
		case "MPL":
			this.status = CricketUtil.SUCCESSFUL;
			griff = CricketFunctions.getBatBallGriffData(CricketUtil.BATSMAN,playerId, cricketService.getTeams(), all_matches, match);
			if(player.getSurname() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamFirstName"
						+ " SET " + player.getFirstname() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamLastName"
						+ " SET " + player.getSurname() + "\0");
			}else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamFirstName"
						+ " SET " + "" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamLastName"
						+ " SET " + player.getFirstname() + "\0");
			}
			for(BatBallGriff grif : griff) {
				row++;
				if(griff.get(row-1).getMatchNumber().equalsIgnoreCase(match.getMatch().getMatchFileName().replace(".json", ""))){
					cont_name = "$Highlight";
					omo_num= 1;
				}else {
					cont_name = "$Dehighlight";
					omo_num= 0;
				}
				print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$BatData$BatDataGrp$BatRow"+ row+ "*ACTIVE SET 1 \0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vBatOmo" + row + " SET " + omo_num + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vImpact" + row + " SET " + 0 + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerName" + row + " SET " + "v "+ grif.getOpponentTeam().getTeamName4()+ "\0");
				
				if(griff.get(row-1).getStatus().equalsIgnoreCase(CricketUtil.STILL_TO_BAT)) {
					if(griff.get(row-1).getHow_out() != null && !griff.get(row-1).getHow_out().trim().isEmpty() && 
							griff.get(row-1).getHow_out().equalsIgnoreCase(CricketUtil.RETIRED_HURT)) {
						print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerRuns" + row + " SET " + griff.get(row-1).getRuns() + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerBalls" + row + " SET " + griff.get(row-1).getBallsFaced() + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerRuns" + row + " SET " + "" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerBalls" + row + " SET " + "DNB" + "\0");

					}
					print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$BatData$BatDataGrp$BatRow"+ row
							+ "$RowAnimation$BatOmo"+cont_name+"$ScoreGrp$NotOutStar*ACTIVE SET 0 \0");
				}else if(griff.get(row-1).getStatus().equalsIgnoreCase(CricketUtil.OUT)) {
					print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$BatData$BatDataGrp$BatRow"+ row
							+ "$RowAnimation$BatOmo"+cont_name+"$ScoreGrp$NotOutStar*ACTIVE SET 0 \0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerRuns" + row + " SET " + griff.get(row-1).getRuns() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerBalls" + row + " SET " + griff.get(row-1).getBallsFaced() + "\0");
				}else if(griff.get(row-1).getStatus().equalsIgnoreCase(CricketUtil.NOT_OUT)) {
					print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$BatData$BatDataGrp$BatRow"+ row
									+ "$RowAnimation$BatOmo"+cont_name+"$ScoreGrp$NotOutStar*ACTIVE SET 1 \0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerRuns" + row + " SET " + griff.get(row-1).getRuns() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerBalls" + row + " SET " + griff.get(row-1).getBallsFaced() + "\0");
				}else {
					print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$All$AllDataGrp$BattingCardAll$BatData$BatData$BatDataGrp$BatRow"+ row
							+ "$RowAnimation$BatOmo"+cont_name+"$ScoreGrp$NotOutStar*ACTIVE SET 0 \0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerRuns" + row + " SET " + "" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBatPlayerBalls" + row + " SET " + "DNP" + "\0");
				}
			}
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vBatRows" + " SET " + griff.size() + "\0");
			

			print_writer.println(
					"-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.180 In$BatDataIn 1.180 \0");
			TimeUnit.MILLISECONDS.sleep(200);
			break;
		}
	}

	public void populateBallGriff(PrintWriter print_writer, String viz_scene, int whichinning, int playerId,
			List<MatchAllData> all_matches, CricketService cricketService, MatchAllData match,
			String session_selected_broadcaster) throws InterruptedException {
		Player player = cricketService.getAllPlayer().stream().filter(plyr ->plyr.getPlayerId() == playerId).findAny().orElse(null);
		List<BatBallGriff> griff = new ArrayList<BatBallGriff>();
		String cont_name = "";
		int omo_num = 0;
		int row = 0;
		switch (session_selected_broadcaster.toUpperCase()) {
		case "MPL":
			griff = CricketFunctions.getBatBallGriffData(CricketUtil.BOWLER,playerId, cricketService.getTeams(), all_matches, match);
			
			if(player.getSurname() != null) {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamFirstName"+ " SET " + player.getFirstname() + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamLastName"+ " SET " + player.getSurname() + "\0");
			}else {
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamFirstName"+ " SET " + "" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tBatBattingTeamLastName"+ " SET " + player.getFirstname() + "\0");
			}
			for(BatBallGriff grif : griff) {
				row++;
				if(griff.get(row-1).getMatchNumber().equalsIgnoreCase(match.getMatch().getMatchFileName().replace(".json", ""))){
					cont_name = "$Highlight";
					omo_num= 1;
				}else {
					cont_name = "$Dehighlight";
					omo_num= 0;
				}
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vImpact" + row + " SET " + "0" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vBallOmo" + row + " SET " + omo_num + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerName" + row + " SET " + "v "+ grif.getOpponentTeam().getTeamName4()+ "\0");
				
				if(griff.get(row-1).getStatus().equalsIgnoreCase("DNB")) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerFigure" + row + " SET " + "" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerOvers" + row + " SET "+ "DNB" + "\0");
				}else if(griff.get(row-1).getStatus().equalsIgnoreCase("BALL")) {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerFigure" + row + " SET " + grif.getWickets() + slashOrDash + grif.getRunsConceded() + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerOvers" + row + " SET "+ grif.getOversBowled() + "\0");
				}else {
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerFigure" + row + " SET " + "" + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "tBallPlayerOvers" + row + " SET "+ "DNP" + "\0");
				}
			}
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "+ "vBatRows" + " SET " + griff.size() + "\0");
		
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.180 In$BatDataIn 1.180 \0");
			 this.status = CricketUtil.SUCCESSFUL;
			break;
		}
	}

