			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tStrikeRate"
					+ row_id + " SET " + bc.getRuns() + " (" + bc.getBalls() + ")" + "\0");
