//							
//						}
//					}
//				}

				if (retired_player == true) {
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tStrikeRate" + row_id + " SET " + "IN AT " + (row_id - 1) + "\0");
				} else {
					print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
							+ "tStrikeRate" + row_id + " SET " + "IN AT " + row_id + "\0");
				}
